namespace ContosoUniversity.Tests.Models;

public class PaginatedListTests
{
    [Fact]
    public void Create_ReturnsCorrectPageItems()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).Select(i => new Student
        {
            ID = i,
            FirstMidName = $"First{i}",
            LastName = $"Last{i}",
            EnrollmentDate = DateTime.Now
        }).AsQueryable();

        // Act
        var result = PaginatedList<Student>.Create(items, 1, 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(3, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_SecondPage_ReturnsCorrectItems()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).Select(i => new Student
        {
            ID = i,
            FirstMidName = $"First{i}",
            LastName = $"Last{i}",
            EnrollmentDate = DateTime.Now
        }).AsQueryable();

        // Act
        var result = PaginatedList<Student>.Create(items, 2, 10);

        // Assert
        Assert.Equal(10, result.Count);
        Assert.Equal(2, result.PageIndex);
        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void Create_LastPage_HasNoNextPage()
    {
        // Arrange
        var items = Enumerable.Range(1, 25).Select(i => new Student
        {
            ID = i,
            FirstMidName = $"First{i}",
            LastName = $"Last{i}",
            EnrollmentDate = DateTime.Now
        }).AsQueryable();

        // Act
        var result = PaginatedList<Student>.Create(items, 3, 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(3, result.PageIndex);
        Assert.True(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_SinglePage_NoPreviousOrNext()
    {
        // Arrange
        var items = Enumerable.Range(1, 5).Select(i => new Student
        {
            ID = i,
            FirstMidName = $"First{i}",
            LastName = $"Last{i}",
            EnrollmentDate = DateTime.Now
        }).AsQueryable();

        // Act
        var result = PaginatedList<Student>.Create(items, 1, 10);

        // Assert
        Assert.Equal(5, result.Count);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(1, result.TotalPages);
        Assert.False(result.HasPreviousPage);
        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        // Arrange
        var items = Enumerable.Empty<Student>().AsQueryable();

        // Act
        var result = PaginatedList<Student>.Create(items, 1, 10);

        // Assert
        Assert.Empty(result);
        Assert.Equal(1, result.PageIndex);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void Constructor_SetsProperties()
    {
        // Arrange
        var items = new List<Student>
        {
            new Student { ID = 1, FirstMidName = "A", LastName = "B", EnrollmentDate = DateTime.Now }
        };

        // Act
        var result = new PaginatedList<Student>(items, 50, 2, 10);

        // Assert
        Assert.Single(result);
        Assert.Equal(2, result.PageIndex);
        Assert.Equal(5, result.TotalPages);
        Assert.True(result.HasPreviousPage);
        Assert.True(result.HasNextPage);
    }
}

