+using ContosoUniversity.Models;
+using ContosoUniversity.Services;
+
+namespace ContosoUniversity.Tests.Services;
+
+public class NotificationServiceTests
+{
+    [Fact]
+    public void SendNotification_WithDisplayName_EnqueuesNotification()
+    {
+        // Arrange
+        var service = new NotificationService();
+
+        // Act
+        service.SendNotification("Student", "1", "John Doe", EntityOperation.CREATE, "Admin");
+
+        // Assert
+        var received = service.ReceiveNotification();
+        Assert.NotNull(received);
+        Assert.Equal("Student", received.EntityType);
+        Assert.Equal("1", received.EntityId);
+        Assert.Equal("CREATE", received.Operation);
+        Assert.Contains("John Doe", received.Message);
+        Assert.Contains("created", received.Message);
+        Assert.Equal("Admin", received.CreatedBy);
+        Assert.False(received.IsRead);
+    }
+
+    [Fact]
+    public void SendNotification_WithoutDisplayName_UsesIdInMessage()
+    {
+        // Arrange
+        var service = new NotificationService();
+
+        // Act
+        service.SendNotification("Course", "42", EntityOperation.UPDATE, "Teacher");
+
+        // Assert
+        var received = service.ReceiveNotification();
+        Assert.NotNull(received);
+        Assert.Contains("ID: 42", received.Message);
+        Assert.Contains("updated", received.Message);
+    }
+
+    [Fact]
+    public void SendNotification_DeleteOperation_GeneratesDeleteMessage()
+    {
+        // Arrange
+        var service = new NotificationService();
+
+        // Act
+        service.SendNotification("Department", "5", "Math", EntityOperation.DELETE, "Admin");
+
+        // Assert
+        var received = service.ReceiveNotification();
+        Assert.NotNull(received);
+        Assert.Contains("deleted", received.Message);
+        Assert.Contains("Math", received.Message);
+    }
+
+    [Fact]
+    public void SendNotification_NullUserName_DefaultsToSystem()
+    {
+        // Arrange
+        var service = new NotificationService();
+
+        // Act
+        service.SendNotification("Student", "1", "Test", EntityOperation.CREATE, null);
+
+        // Assert
+        var received = service.ReceiveNotification();
+        Assert.NotNull(received);
+        Assert.Equal("System", received.CreatedBy);
+    }
+
+    [Fact]
+    public void ReceiveNotification_EmptyQueue_ReturnsNull()
+    {
+        // Arrange
+        var service = new NotificationService();
+        // Drain any existing items
+        while (service.ReceiveNotification() != null) { }
+
+        // Act
+        var result = service.ReceiveNotification();
+
+        // Assert
+        Assert.Null(result);
+    }
+
+    [Fact]
+    public void SendNotification_MultipleMessages_ReceivesInFifoOrder()
+    {
+        // Arrange
+        var service = new NotificationService();
+        // Drain existing
+        while (service.ReceiveNotification() != null) { }
+
+        // Act
+        service.SendNotification("A", "1", "First", EntityOperation.CREATE);
+        service.SendNotification("B", "2", "Second", EntityOperation.UPDATE);
+        service.SendNotification("C", "3", "Third", EntityOperation.DELETE);
+
+        // Assert
+        var first = service.ReceiveNotification();
+        var second = service.ReceiveNotification();
+        var third = service.ReceiveNotification();
+        Assert.Equal("A", first!.EntityType);
+        Assert.Equal("B", second!.EntityType);
+        Assert.Equal("C", third!.EntityType);
+    }
+
+    [Fact]
+    public void MarkAsRead_DoesNotThrow()
+    {
+        // Arrange
+        var service = new NotificationService();
+
+        // Act & Assert - should not throw
+        var exception = Record.Exception(() => service.MarkAsRead(999));
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void Dispose_DoesNotThrow()
+    {
+        // Arrange
+        var service = new NotificationService();
+
+        // Act & Assert
+        var exception = Record.Exception(() => service.Dispose());
+        Assert.Null(exception);
+    }
+
+    [Fact]
+    public void SendNotification_SetsCreatedAtToRecentTime()
+    {
+        // Arrange
+        var service = new NotificationService();
+        var before = DateTime.Now.AddSeconds(-1);
+
+        // Act
+        service.SendNotification("Test", "1", "Entity", EntityOperation.CREATE, "User");
+
+        // Assert
+        var received = service.ReceiveNotification();
+        Assert.NotNull(received);
+        Assert.True(received.CreatedAt >= before);
+        Assert.True(received.CreatedAt <= DateTime.Now.AddSeconds(1));
+    }
+}
+

